import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.DqYch1Cg.js";const b=JSON.parse('{"title":"HTTP 缓存：从字段到发布策略","description":"","frontmatter":{},"headers":[],"relativePath":"概念与原理/04http/s_http_9-cache_strategy.md","filePath":"概念与原理/04http/s_http_9-cache_strategy.md","lastUpdated":1794211306000}'),d={name:"概念与原理/04http/s_http_9-cache_strategy.md"};function n(o,t,p,c,l,h){return a(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="http-缓存-从字段到发布策略" tabindex="-1">HTTP 缓存：从字段到发布策略 <a class="header-anchor" href="#http-缓存-从字段到发布策略" aria-label="Permalink to &quot;HTTP 缓存：从字段到发布策略&quot;">​</a></h1><h2 id="一次缓存决策" tabindex="-1">一次缓存决策 <a class="header-anchor" href="#一次缓存决策" aria-label="Permalink to &quot;一次缓存决策&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>存在可用缓存？</span></span>
<span class="line"><span>  → 在新鲜期内且允许直接复用：使用缓存</span></span>
<span class="line"><span>  → 需要验证：携带 ETag / 修改时间发送条件请求</span></span>
<span class="line"><span>      → 未变化：304，复用已存响应体并更新元数据</span></span>
<span class="line"><span>      → 已变化：200，使用新内容并按策略存储</span></span>
<span class="line"><span>  → 不允许存储 / 未命中：请求服务端</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>304 是条件请求的响应，不是重定向。ETag 是不透明的版本标识，不一定是文件哈希；Last-Modified 描述源表示的修改时间，不是本地缓存创建时间。两类验证条件同时存在时，If-None-Match 有优先处理规则。</p><table tabindex="0"><thead><tr><th>指令</th><th>准确理解</th></tr></thead><tbody><tr><td><code>max-age=600</code></td><td>定义新鲜期，计算年龄还涉及 Date / Age 等；不是下载后永远固定倒计时</td></tr><tr><td><code>no-cache</code></td><td>可以存储，但每次复用前需要成功验证</td></tr><tr><td><code>no-store</code></td><td>不允许缓存存储当前请求 / 响应；不是清空全部已有缓存的按钮</td></tr><tr><td><code>private</code></td><td>禁止共享缓存存储，可允许浏览器私有缓存</td></tr><tr><td><code>s-maxage</code></td><td>针对共享缓存的新鲜度，优先于 max-age / Expires</td></tr><tr><td><code>must-revalidate</code></td><td>过期后必须验证，不能随意拿陈旧响应顶替</td></tr></tbody></table><p><code>no-store</code> 已禁止私有与共享缓存存储，不是必须再加 private 才有效。private 适合“允许个人缓存但禁止共享”的响应。HTTP 缓存指令也不能代替权限控制，不能假设它一定清除 Service Worker 的程序化 Cache Storage。</p><h2 id="面向发布的组合" tabindex="-1">面向发布的组合 <a class="header-anchor" href="#面向发布的组合" aria-label="Permalink to &quot;面向发布的组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>常见策略</th><th>代价与边界</th></tr></thead><tbody><tr><td>带内容哈希的 JS / CSS</td><td>长 max-age，可配 immutable</td><td>URL 内容应不可变；发布要保留旧资源供旧页面引用</td></tr><tr><td>HTML 入口</td><td>no-cache，结合 ETag 验证</td><td>仍会访问网络验证，便于发现新引用</td></tr><tr><td>个性化 API</td><td>按敏感程度选择 private 或 no-store</td><td>CDN 配置与用户隔离必须一起检查</td></tr><tr><td>公共可缓存 API</td><td>明确新鲜度、Vary 与失效方式</td><td>不把 Cookie / Authorization 用户数据误存为公共内容</td></tr></tbody></table><p>缓存策略是客户端、反向代理、CDN 与源站的协作结果，源站设了字段不代表 CDN 一定照做。带 query 的资源也可以缓存，POST 与 GET 的缓存规则应按协议和实现核实，不能靠“后缀有问号就不缓存”的经验判断。</p><h2 id="一个验证实验" tabindex="-1">一个验证实验 <a class="header-anchor" href="#一个验证实验" aria-label="Permalink to &quot;一个验证实验&quot;">​</a></h2><p>在自己的本地服务上配置 ETag 和 <code>Cache-Control: no-cache</code>，第一次访问观察200和响应体；再次访问观察 If-None-Match 与304；改变内容后验证返回200与新标识。再切换成短 max-age，比较新鲜期内是否发请求。</p><p>DevTools 的 Disable cache、硬刷新与普通导航行为不同，记录实验操作，否则容易把调试设置当线上缓存失效。缓存命中还应区分内存、磁盘、Service Worker 与 CDN。</p><p>关联阅读：<a href="./s_http_4-cache">HTTP 缓存详解</a>、<a href="/FE-prepare-interview/概念与原理/06opt/s_opt_12-storage_cache">浏览器存储与离线缓存</a>。</p><blockquote><p>来源：<a href="https://github.com/Fridolph/Fridolph/tree/c3a1eda8e0f7fe08d8ec54e07d07db514cbfc5d7/HTTP/%E6%B5%8F%E8%A7%88%E5%99%A8%E7%BC%93%E5%AD%98" target="_blank" rel="noreferrer">个人缓存笔记</a>（原笔记参考 <a href="https://segmentfault.com/a/1190000008377508" target="_blank" rel="noreferrer">缓存机制文章</a>）；<a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP/Guides/Caching" target="_blank" rel="noreferrer">MDN HTTP 缓存</a>；<a href="https://www.rfc-editor.org/rfc/rfc9111" target="_blank" rel="noreferrer">RFC 9111</a>。</p></blockquote>`,14)])])}const _=e(d,[["render",n]]);export{b as __pageData,_ as default};
